const T = 3;
const ranges = {s1:[0,100], s2:[2,400], s3:[0,1]};
const sql = [];
let cycles = 0;
const numeric = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;
for (const raw of String(msg.payload).replace(/^\uFEFF/, '').split(/\r?\n/)) {
  const line = raw.trim();
  if (!line) continue;
  const parts = line.split(/\s+/);
  const kind = parts.shift();
  if (!['DATA','EVENT'].includes(kind)) {
    node.error('Нужен исходный лог DATA/EVENT без перевода.', msg);
    return null;
  }
  const f = {};
  for (const part of parts) {
    const pos = part.indexOf('=');
    if (pos < 1) { node.error('Неверная строка: '+line, msg); return null; }
    f[part.slice(0,pos)] = part.slice(pos+1);
  }
  const n = Number(f.n);
  if (!/^\d+$/.test(f.n || '') || !Number.isSafeInteger(n) || n<1 || !Number.isSafeInteger(n*T)) {
    node.error('Неверный номер измерения.', msg);
    return null;
  }
  const t = n*T;
  if (kind === 'DATA') {
    cycles++;
    for (const s of ['s1','s2','s3']) {
      const v = numeric.test(f[s] || '') ? Number(f[s]) : NaN;
      if (Number.isFinite(v)) {
        sql.push(`INSERT INTO readings(n,t_s,sensor,value) VALUES(${n},${t},'${s}',${v});`);
      }
      if (!Number.isFinite(v) || v<ranges[s][0] || v>ranges[s][1] || (s==='s3' && v!==0 && v!==1)) {
        sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'FAULT','датчик ${s} вне диапазона');`);
      }
    }
  } else {
    if (!['THRESHOLD','NORMAL'].includes(f.type)) {
      node.error('Неверный тип события.', msg);
      return null;
    }
    sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'${f.type}','');`);
  }
}
if (!cycles) { node.error('Нет строк DATA. База не изменена.', msg); return null; }
const head = 'BEGIN;\nDELETE FROM readings;\nDELETE FROM events;\n' + "DELETE FROM sqlite_sequence WHERE name IN ('readings','events');\n";
const tail = "\nCOMMIT;\nSELECT 'readings',COUNT(*) FROM readings;\nSELECT 'events',COUNT(*) FROM events;\n";
node.status({fill:'green',shape:'dot',text:cycles+' циклов'});
return [null,{payload:head+sql.join('\n')+tail}];
